//! Writes the Rust tables of one version. The text goes through `rustfmt`
//! before it is written, so the files are `cargo fmt` clean.

use crate::error::GenError;
use crate::resolve::{Dict, GroupShape, Member, Section};
use std::fmt::Write as _;

/// The text of the notice at the top of each generated file.
pub struct Notice<'a> {
    pub source_name: &'a str,
    pub source_sha256: &'a str,
    pub copyright: &'a str,
}

fn field_type(repository_type: &str) -> Result<&'static str, GenError> {
    Ok(match repository_type {
        "String" => "String",
        "int" => "Int",
        "float" => "Float",
        "Qty" => "Qty",
        "Price" => "Price",
        "PriceOffset" => "PriceOffset",
        "Amt" => "Amt",
        "Percentage" => "Percentage",
        "char" => "Char",
        "Boolean" => "Boolean",
        "Length" => "Length",
        "SeqNum" => "SeqNum",
        "NumInGroup" => "NumInGroup",
        "DayOfMonth" => "DayOfMonth",
        "Currency" => "Currency",
        "Exchange" => "Exchange",
        "Country" => "Country",
        "MultipleValueString" => "MultipleValueString",
        "UTCTimestamp" => "UtcTimestamp",
        "UTCTimeOnly" => "UtcTimeOnly",
        "UTCDate" | "UTCDateOnly" => "UtcDate",
        "LocalMktDate" => "LocalMktDate",
        "MonthYear" => "MonthYear",
        "data" => "Data",
        other => return Err(GenError::data(format!("unknown field type {other}"))),
    })
}

/// `NoPartyIDs` becomes `NO_PARTY_IDS`.
pub fn screaming_snake(name: &str) -> String {
    let name = name.replace("IDs", "Ids");
    let chars: Vec<char> = name.chars().collect();
    let mut out = String::new();
    for (index, current) in chars.iter().enumerate() {
        let previous = index.checked_sub(1).map(|i| chars[i]);
        let next = chars.get(index + 1);
        let boundary = current.is_uppercase()
            && previous.is_some_and(|p| {
                p.is_lowercase()
                    || p.is_ascii_digit()
                    || (p.is_uppercase() && next.is_some_and(|n| n.is_lowercase()))
            });
        if boundary {
            out.push('_');
        }
        out.push(current.to_ascii_uppercase());
    }
    out
}

/// One Rust name for each group: the name of the count field, with `_2`,
/// `_3` for a second and third group that has the same count tag.
fn group_names(dict: &Dict) -> Result<Vec<String>, GenError> {
    let mut names: Vec<String> = Vec::new();
    for shape in &dict.groups {
        let field = dict
            .fields
            .iter()
            .find(|field| field.tag == shape.count_tag)
            .ok_or_else(|| {
                GenError::data(format!("group count tag {} unknown", shape.count_tag))
            })?;
        let base = screaming_snake(&field.name);
        let mut name = base.clone();
        let mut number = 2;
        while names.contains(&name) {
            name = format!("{base}_{number}");
            number += 1;
        }
        names.push(name);
    }
    Ok(names)
}

fn emit_header(out: &mut String, dict: &Dict, notice: &Notice<'_>) {
    let _ = write!(
        out,
        "// @generated by crates/fix-dict-gen. Do not edit. Run tools/regen-fix-dict.sh.\n\
         //\n\
         // Source: {}\n\
         // SHA-256 of the source ZIP: {}\n\
         // {}\n\
         // License: Apache-2.0, see LICENSES/FIX-Repository-Apache-2.0.txt.\n\
         // Content: all messages, fields, enum values, and repeating groups of {}.\n\n",
        notice.source_name, notice.source_sha256, notice.copyright, dict.begin_string,
    );
    out.push_str(
        "use crate::schema::build::{field, fld, grp, message, section, value};\n\
         use crate::schema::{Dictionary, FieldDef, FieldType as T, MessageDef, Section};\n\
         use fix_codec::GroupDef;\n\n",
    );
}

fn emit_fields(out: &mut String, dict: &Dict) -> Result<(), GenError> {
    let _ = writeln!(out, "static FIELDS: [FieldDef; {}] = [", dict.fields.len());
    for field in &dict.fields {
        let values: Vec<String> = field
            .values
            .iter()
            .map(|(value, name)| format!("value({value:?}, {name:?})"))
            .collect();
        let _ = writeln!(
            out,
            "field({}, {:?}, T::{}, &[{}]),",
            field.tag,
            field.name,
            field_type(&field.ty)?,
            values.join(", ")
        );
    }
    out.push_str("];\n\n");
    Ok(())
}

fn tag_list(fields: &[(u32, bool)], required: bool) -> String {
    let mut tags: Vec<u32> = fields
        .iter()
        .filter(|(_, r)| *r == required)
        .map(|(tag, _)| *tag)
        .collect();
    tags.sort_unstable();
    let tags: Vec<String> = tags.iter().map(u32::to_string).collect();
    format!("&[{}]", tags.join(", "))
}

fn section_text(section: &Section, names: &[String]) -> String {
    let mut groups: Vec<&String> = section.groups.iter().map(|index| &names[*index]).collect();
    groups.sort();
    let groups: Vec<String> = groups.iter().map(|name| format!("&{name}")).collect();
    format!(
        "section({}, {}, &[{}])",
        tag_list(&section.fields, true),
        tag_list(&section.fields, false),
        groups.join(", ")
    )
}

fn emit_messages(out: &mut String, dict: &Dict, names: &[String]) {
    let _ = writeln!(
        out,
        "static MESSAGES: [MessageDef; {}] = [",
        dict.messages.len()
    );
    for message in &dict.messages {
        let _ = writeln!(
            out,
            "message({:?}, {:?}, {}),",
            message.msg_type,
            message.name,
            section_text(&message.body, names)
        );
    }
    out.push_str("];\n\n");
    let _ = writeln!(
        out,
        "static HEADER: Section = {};\n",
        section_text(&dict.header, names)
    );
    let _ = writeln!(
        out,
        "static TRAILER: Section = {};\n",
        section_text(&dict.trailer, names)
    );
}

fn member_text(member: &Member, names: &[String]) -> String {
    match member {
        Member::Field(tag) => format!("fld({tag})"),
        Member::Group(index) => format!("grp(&{})", names[*index]),
    }
}

fn field_name(dict: &Dict, tag: u32) -> &str {
    dict.fields
        .iter()
        .find(|field| field.tag == tag)
        .map_or("?", |field| field.name.as_str())
}

/// The most users that a group comment names.
const USERS_SHOWN: usize = 4;

/// The messages (and the header) that have the group, as text for a comment.
fn used_in(dict: &Dict, group: usize) -> String {
    let mut users: Vec<String> = dict
        .messages
        .iter()
        .filter(|message| message.body.groups.contains(&group))
        .map(|message| format!("message {}", message.msg_type))
        .collect();
    if dict.header.groups.contains(&group) {
        users.push("the header".to_owned());
    }
    let nested = dict
        .groups
        .iter()
        .filter(|other| other.members.contains(&Member::Group(group)))
        .count();
    if nested > 0 {
        users.push(format!("{nested} other group(s)"));
    }
    if users.is_empty() {
        return "no message".to_owned();
    }
    if users.len() > USERS_SHOWN {
        let more = users.len() - USERS_SHOWN;
        users.truncate(USERS_SHOWN);
        users.push(format!("{more} more"));
    }
    users.join(", ")
}

fn emit_groups(out: &mut String, dict: &Dict, names: &[String]) {
    let mut order: Vec<usize> = (0..dict.groups.len()).collect();
    order.sort_by(|a, b| names[*a].cmp(&names[*b]));
    for index in order {
        let GroupShape { count_tag, members } = &dict.groups[index];
        let members: Vec<String> = members.iter().map(|m| member_text(m, names)).collect();
        let _ = write!(
            out,
            "/// {} ({count_tag}), used in {}.\n\
             static {}: GroupDef<'static> = GroupDef {{\n\
             count_tag: {count_tag},\n\
             members: &[{}],\n\
             }};\n\n",
            field_name(dict, *count_tag),
            used_in(dict, index),
            names[index],
            members.join(", ")
        );
    }
}

/// The Rust source of one version, before `rustfmt`.
pub fn emit(dict: &Dict, notice: &Notice<'_>) -> Result<String, GenError> {
    let names = group_names(dict)?;
    let mut out = String::new();
    emit_header(&mut out, dict, notice);
    let _ = write!(
        out,
        "/// The dictionary of {}.\n\
         pub static DICTIONARY: Dictionary = Dictionary {{\n\
         begin_string: {:?},\n\
         fields: &FIELDS,\n\
         messages: &MESSAGES,\n\
         header: HEADER,\n\
         trailer: TRAILER,\n\
         data_pairs: &DATA_PAIRS,\n\
         }};\n\n",
        dict.begin_string, dict.begin_string
    );
    let pairs: Vec<String> = dict
        .data_pairs
        .iter()
        .map(|(length, data)| format!("({length}, {data})"))
        .collect();
    let _ = write!(
        out,
        "/// Length fields and the data fields that they give the length of.\n\
         static DATA_PAIRS: [(u32, u32); {}] = [{}];\n\n",
        pairs.len(),
        pairs.join(", ")
    );
    emit_fields(&mut out, dict)?;
    emit_messages(&mut out, dict, &names);
    emit_groups(&mut out, dict, &names);
    Ok(out)
}

#[cfg(test)]
mod tests {
    use super::screaming_snake;

    #[test]
    fn group_names_become_rust_statics() {
        assert_eq!(screaming_snake("NoPartyIDs"), "NO_PARTY_IDS");
        assert_eq!(screaming_snake("NoMDEntries"), "NO_MD_ENTRIES");
        assert_eq!(screaming_snake("NoSecurityAltID"), "NO_SECURITY_ALT_ID");
        assert_eq!(screaming_snake("NoNested2PartyIDs"), "NO_NESTED2_PARTY_IDS");
    }
}
